    let settled = false;
    const done = () => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      layer.off?.("load", done);
      layer.off?.("tileerror", done);
      resolve();
    };
    const timer = setTimeout(done, timeoutMs);
    layer.on("load", done);
    layer.on("tileerror", done);
    if (typeof layer.isLoading === "function" && !layer.isLoading()) {
      setTimeout(done, 80);
    }
  });
}

