    payload.endpointSharesPercent[0] === 0 && payload.endpointSharesPercent[1] === 100
    ? payload.endpointStagesInTenthsFtNavd88?.[String(feature.id)] : null;
  const thresholds = [
    [0, endpoints?.[0]],
